const inputItem = $input.first();
const ctx = inputItem.json;
const allBinary = inputItem.binary ?? {};

const keys = Array.isArray(ctx.binaryKeys) && ctx.binaryKeys.length
  ? ctx.binaryKeys
  : Object.keys(allBinary);

if (!keys.length) throw new Error('FILE_MISSING: No binary properties were received.');

const documentTypes = new Set(['pdf','docx','pptx']);
const imageTypes = new Set(['png','jpg','jpeg']);
const documentMimes = new Set([
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation'
]);
const imageMimes = new Set(['image/png','image/jpeg','image/jpg']);
const csvMimes = new Set(['text/csv','application/csv','application/vnd.ms-excel']);

const sessionId = String(ctx.sessionId ?? 'unknown_session');
const collectionName = 'chat_' + sessionId.replace(/[^a-zA-Z0-9]/g, '_').slice(0, 48);

function createUuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.floor(Math.random() * 16);
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const requestId = String(ctx.requestId ?? ctx.correlationId ?? ctx.userMessageId ?? ctx.messageId ?? createUuid());
const replyToMessageId = ctx.userMessageId ?? ctx.messageId ?? ctx.replyToMessageId ?? null;

// MOF_DOCUMENT_LIMIT_V1 (UAT1-FB-053): at most this many documents per chat.
// Files over the limit take the rejected route and are named under the answer.
const MAX_DOCUMENTS_PER_CHAT = 5;
const alreadyInChat = Number(ctx.session_document_count);
let documentSlots = Number.isFinite(alreadyInChat) ? Math.max(0, MAX_DOCUMENTS_PER_CHAT - alreadyInChat) : Infinity;

return keys.map((key, index) => {
  const binaryFile = allBinary[key];
  if (!binaryFile) throw new Error(`FILE_MISSING: Binary property "${key}" is unavailable.`);

  const name = String(binaryFile.fileName ?? `upload_${index + 1}`).replace(/[\r\n]/g, '');
  const extension = String(binaryFile.fileExtension ?? name.split('.').pop() ?? '')
    .replace(/^\./, '').toLowerCase();
  const mime = String(binaryFile.mimeType ?? '').toLowerCase().split(';')[0].trim();

  let route = 'unsupported';
  if (documentTypes.has(extension) || documentMimes.has(mime)) route = 'document';
  else if (imageTypes.has(extension) || imageMimes.has(mime)) route = 'image';
  else if (extension === 'csv' || csvMimes.has(mime)) route = 'csv';
  let limitExceeded = false;
  if (route !== 'unsupported') {
    if (documentSlots > 0) documentSlots -= 1;
    else { route = 'unsupported'; limitExceeded = true; }
  }

  return {
    json: {
      ...ctx,
      sessionId,
      requestId,
      correlationId: String(ctx.correlationId ?? requestId),
      replyToMessageId,
      hasFile: true,
      uploadFileCount: keys.length,
      binaryKey: key,
      fileSequence: index + 1,
      file: {
        binaryKey: 'data',
        originalBinaryKey: key,
        name,
        extension,
        mimeType: mime,
        size: binaryFile.fileSize ?? null,
      },
      route,
      limitExceeded,
      maxDocumentsPerChat: MAX_DOCUMENTS_PER_CHAT,
      documentId: createUuid(),
      collectionName,
    },
    binary: { data: binaryFile },
    pairedItem: { item: 0 },
  };
});
